{"results": [{"id": "hp_doc_d14d03af8aed61f99c6fadc80da9ac514a4661c741e75117e33a51ea80bb2991", "title": "1988 1000 km of Silverstone", "text": "The 1988 Autosport 1000 km was the fourth round of the 1988 World Sportscar Championship season. It took place at the Silverstone Circuit, United Kingdom on May 8, 1988.", "score": 33.9184}, {"id": "hp_doc_bc1fb25af8712b7e818a7f36619d7950d9fc44c6add3724e11031a38487fc062", "title": "2008 1000 km of Silverstone", "text": "The 2008 Autosport 1000 km of Silverstone was the fifth and final round of the 2008 Le Mans Series season. It took place at the Silverstone Circuit, Great Britain, on 14 September 2008. The race was attended by a record crowd of 53,000 spectators.", "score": 23.6932}, {"id": "hp_doc_6bb1379722d1bfaf327a4a7a6858ead4fb9095f1b0fb93cf51873d51f2b1016d", "title": "2010 1000 km of Silverstone", "text": "The 2010 Autosport 1000 km of Silverstone was the fifth and final round of the 2010 Le Mans Series season and the inaugural race of the Intercontinental Le Mans Cup. It take place at Silverstone Circuit on 12 September. Manufacturers in the LMP1 and GT2 categories are eligible to compete for points in the ILMC, will designated teams in all categories except Formula Le Mans are also competing for an ILMC title.", "score": 21.0301}], "remaining_searches": 2}
